Office.onReady((info) => {
    // Check if the host is Outlook
    if (info.host === Office.HostType.Outlook) {
        // Run the function to extract and display message data
        displayMessageDetails();
    }
});

function displayMessageDetails() {
    // Access the selected item (email) in Outlook
    const item = Office.context.mailbox.item;

    if (item) {
        // 1. Get Sender Info
        if (item.from) {
            const senderName = item.from.displayName;
            const senderEmail = item.from.emailAddress;
            document.getElementById("sender").innerText = `${senderName} (${senderEmail})`;
        } else {
            document.getElementById("sender").innerText = "No sender information available.";
        }

        // 2. Get Subject
        if (item.subject) {
            document.getElementById("subject").innerText = item.subject;
        } else {
            document.getElementById("subject").innerText = "(No Subject)";
        }

        // 3. Get Received Date
        if (item.dateTimeCreated) {
            const receivedDate = new Date(item.dateTimeCreated);
            // Format date to local readable format
            document.getElementById("dateReceived").innerText = receivedDate.toLocaleString();
        } else {
            document.getElementById("dateReceived").innerText = "No date available.";
        }
    } else {
        document.getElementById("sender").innerText = "No message selected.";
        document.getElementById("subject").innerText = "";
        document.getElementById("dateReceived").innerText = "";
    }
}